<div class="form-field"><label for="username">Username <span aria-hidden="true">*</span></label><input id="username" name="username" maxlength="50" autocomplete="username" value="<?= esc(old('username', $user['username'] ?? ''), 'attr') ?>" required><?php if (isset($formErrors['username'])): ?><p class="field-error"><?= esc($formErrors['username']) ?></p><?php endif; ?></div>
<div class="form-field"><label for="full_name">Full name <span aria-hidden="true">*</span></label><input id="full_name" name="full_name" maxlength="100" autocomplete="name" value="<?= esc(old('full_name', $user['full_name'] ?? ''), 'attr') ?>" required><?php if (isset($formErrors['full_name'])): ?><p class="field-error"><?= esc($formErrors['full_name']) ?></p><?php endif; ?></div>
