<div class="form-field form-field-wide"><label for="avatar">Profile image <span class="optional-label">Optional</span></label><?php if ($user !== null): ?><img class="avatar-preview" src="<?= esc(! empty($user['avatar']) ? base_url('uploads/' . $user['avatar']) : base_url('assets/images/user-placeholder.svg'), 'attr') ?>" alt="Current profile image" width="76" height="76"><?php endif; ?><input id="avatar" name="avatar" type="file" accept="image/jpeg,image/png,.jpg,.jpeg,.png"><small>JPG or PNG, up to 2 MB. The image is safely re-encoded and resized to 256 × 256. Leaving it blank keeps the current image.</small><?php if (isset($formErrors['avatar'])): ?><p class="field-error"><?= esc($formErrors['avatar']) ?></p><?php endif; ?></div>
